/**
 * S289 — PERĖMIMAS IŠ PREKĖS PUSLAPIO ESAMIEMS AUGINTINIAMS.
 *
 * Kelias naujam klientui buvo uždarytas (anketa perima duomenis), o turintis
 * augintinių atsidurdavo sąraše ir jo darbas prapuldavo — mygtukas žadėjo
 * „išsaugoti", o realiai tik nuvesdavo.
 *
 * PAGRINDINĖ TAISYKLĖ: NIEKO NEPERRAŠOM TYLIAI.
 * Jei profilyje 11 kg, o skaičiuoklėje nurodyta 13 kg — klausiam. Tas pats su
 * maistu. Žmogus pasinaudojo skaičiuokle, o ne paprašė pakeisti profilį.
 *
 * Įterpiama į pet-profile.js kaip savarankiškas modulis.
 */
(function () {
	'use strict';

	var HKEY = 'petshop_calc_handoff';

	function read() {
		try {
			var raw = window.localStorage.getItem(HKEY);
			if (!raw) { return null; }
			var h = JSON.parse(raw);
			// 2 val. — vėliau žmogus greičiausiai jau kitame kontekste.
			if (!h || !h.ts || (Date.now() - h.ts) > 2 * 60 * 60 * 1000) { clear(); return null; }
			return h;
		} catch (e) { return null; }
	}
	function clear() {
		try { window.localStorage.removeItem(HKEY); } catch (e) {}
	}

	window.PetshopCalcHandoff = {
		read: read,
		clear: clear,

		/**
		 * Ar yra ką rodyti. Grąžinam būseną, o ne sprendimą — piešimas atskirai.
		 *   none        — perėmimo nėra
		 *   no_species  — tos rūšies augintinio paskyroje nėra
		 *   single      — vienas tos rūšies
		 *   choose      — keli
		 */
		state: function (pets) {
			var h = read();
			if (!h) { return { mode: 'none' }; }
			var same = (pets || []).filter(function (p) {
				return !h.species || p.species === h.species;
			});
			if (!same.length) { return { mode: 'no_species', h: h }; }
			if (same.length === 1) { return { mode: 'single', h: h, pet: same[0] }; }
			return { mode: 'choose', h: h, pets: same };
		},

		/**
		 * Konfliktai tarp profilio ir skaičiavimo. Grąžinam FAKTUS —
		 * sprendimą priima žmogus.
		 */
		conflicts: function (pet, h) {
			var out = [];
			var pw = (pet.current_weight_kg !== null && pet.current_weight_kg !== undefined && pet.current_weight_kg !== '')
				? parseFloat(pet.current_weight_kg) : null;
			var hw = h.weight_kg ? parseFloat(h.weight_kg) : null;
			if (pw !== null && hw !== null && Math.abs(pw - hw) > 0.05) {
				out.push({ field: 'weight', current: pw, incoming: hw });
			}
			var pp = pet.primary_product_id ? parseInt(pet.primary_product_id, 10) : null;
			var hp = h.product_id ? parseInt(h.product_id, 10) : null;
			if (pp && hp && pp !== hp) {
				out.push({
					field: 'product',
					current: pet.primary_product_name || ('#' + pp),
					incoming: h.product_name || ('#' + hp)
				});
			}
			return out;
		},

		/**
		 * Išsaugojimas. Siunčiam TIK tai, ką žmogus patvirtino.
		 * Svoris — atskiru endpointu (pet-profile jo nepriima), produktas —
		 * per pet-profile merge su pet_id.
		 */
		save: function (petId, h, apply, REST, NONCE) {
			var jobs = [];
			if (apply.weight && h.weight_kg) {
				jobs.push(fetch(REST + '/feeding-pet-weight', {
					method: 'POST',
					headers: { 'Content-Type': 'application/json', 'X-WP-Nonce': NONCE },
					credentials: 'same-origin',
					body: JSON.stringify({ pet_id: petId, weight_kg: parseFloat(h.weight_kg) })
				}));
			}
			if (apply.product && h.product_id) {
				jobs.push(fetch(REST + '/pet-profile', {
					method: 'POST',
					headers: { 'Content-Type': 'application/json', 'X-WP-Nonce': NONCE },
					credentials: 'same-origin',
					body: JSON.stringify({
						pet_id: petId,
						primary_product_id: parseInt(h.product_id, 10),
						primary_product_name: h.product_name || null,
						primary_product_sku: h.product_sku || null,
						primary_product_package: h.product_package || null
					})
				}));
			}
			if (!jobs.length) { return Promise.resolve(true); }
			return Promise.all(jobs).then(function () { return true; });
		}
	};
})();

